import * as crypto from 'crypto';
import { EventEmitter } from 'events';

interface CacheEntry {
  data: Buffer;
  iv: Buffer;
  tag: Buffer;
  timestamp: number;
}

interface CircuitState {
  failures: number;
  lastFailure: number;
  state: 'closed' | 'open' | 'half-open';
}

class EncryptionProvider {
  private readonly algorithm = 'aes-256-gcm';
  private readonly key: Buffer;
  private counter: Buffer;
  private readonly nodeId: Buffer;

  constructor(masterKey: string, nodeId: string) {
    // Derive a per-node salt rather than using a hardcoded static salt.
    // This keeps derivation deterministic (needed for decrypt) while ensuring
    // distinct instances/nodes produce distinct salts, mitigating precomputation.
    const salt = crypto
      .createHash('sha256')
      .update('cache-salt-v2')
      .update(nodeId)
      .digest();
    this.key = crypto.scryptSync(masterKey, salt, 32);
    this.nodeId = crypto.createHash('sha256').update(nodeId).digest().slice(0, 4);
    this.counter = Buffer.alloc(8);
    crypto.randomFillSync(this.counter);
  }

  private generateIV(): Buffer {
    // 12-byte IV: 4 bytes nodeId + 8 bytes counter
    const iv = Buffer.alloc(12);
    this.nodeId.copy(iv, 0);
    this.counter.copy(iv, 4);
    this.incrementCounter();
    return iv;
  }

  private incrementCounter(): void {
    for (let i = 0; i < this.counter.length; i++) {
      this.counter[i]++;
      if (this.counter[i] !== 0) break;
    }
  }

  encrypt(plaintext: Buffer): { ciphertext: Buffer; iv: Buffer; tag: Buffer } {
    const iv = this.generateIV();
    const cipher = crypto.createCipheriv(this.algorithm, this.key, iv);
    const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
    const tag = cipher.getAuthTag();
    return { ciphertext, iv, tag };
  }

  decrypt(ciphertext: Buffer, iv: Buffer, tag: Buffer): Buffer {
    const decipher = crypto.createDecipheriv(this.algorithm, this.key, iv);
    decipher.setAuthTag(tag);
    return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  }

  resetState(): void {
    // Called during recovery - generate fresh random counter
    crypto.randomFillSync(this.counter);
  }
}

class CircuitBreaker extends EventEmitter {
  private circuits: Map<string, CircuitState> = new Map();
  private readonly threshold: number;
  private readonly resetTimeout: number;

  constructor(threshold = 5, resetTimeout = 30000) {
    super();
    this.threshold = threshold;
    this.resetTimeout = resetTimeout;
  }

  canExecute(endpoint: string): boolean {
    const circuit = this.circuits.get(endpoint);
    if (!circuit) return true;
    if (circuit.state === 'closed') return true;
    if (circuit.state === 'open') {
      if (Date.now() - circuit.lastFailure > this.resetTimeout) {
        circuit.state = 'half-open';
        this.emit('half-open', endpoint);
        return true;
      }
      return false;
    }
    return true;
  }

  recordSuccess(endpoint: string): void {
    const circuit = this.circuits.get(endpoint);
    if (circuit) {
      circuit.failures = 0;
      circuit.state = 'closed';
      this.emit('closed', endpoint);
    }
  }

  recordFailure(endpoint: string): void {
    let circuit = this.circuits.get(endpoint);
    if (!circuit) {
      circuit = { failures: 0, lastFailure: 0, state: 'closed' };
      this.circuits.set(endpoint, circuit);
    }
    circuit.failures++;
    circuit.lastFailure = Date.now();
    if (circuit.failures >= this.threshold) {
      circuit.state = 'open';
      this.emit('open', endpoint);
    }
  }
}

export class DistributedCacheClient {
  private readonly encryption: EncryptionProvider;
  private readonly circuitBreaker: CircuitBreaker;
  private readonly localCache: Map<string, CacheEntry> = new Map();
  private readonly endpoints: string[];
  private recoveryInProgress = false;

  constructor(masterKey: string, nodeId: string, endpoints: string[]) {
    this.encryption = new EncryptionProvider(masterKey, nodeId);
    this.circuitBreaker = new CircuitBreaker(3, 15000);
    this.endpoints = endpoints;
    this.setupCircuitListeners();
  }

  private setupCircuitListeners(): void {
    this.circuitBreaker.on('open', (endpoint: string) => {
      console.log(`Circuit opened for ${endpoint}, initiating recovery`);
      this.initiateRecovery(endpoint);
    });

    this.circuitBreaker.on('closed', (_endpoint: string) => {
      if (this.recoveryInProgress) {
        this.recoveryInProgress = false;
        // Reset encryption state after recovery completes
        this.encryption.resetState();
      }
    });
  }

  private async initiateRecovery(endpoint: string): Promise<void> {
    this.recoveryInProgress = true;
    // Simulate failover to backup endpoint
    const backupEndpoint = this.endpoints.find(e => e !== endpoint);
    if (backupEndpoint) {
      console.log(`Failing over to ${backupEndpoint}`);
    }
  }

  async set(key: string, value: Buffer): Promise<void> {
    const endpoint = this.selectEndpoint(key);
    if (!this.circuitBreaker.canExecute(endpoint)) {
      throw new Error(`Circuit open for endpoint: ${endpoint}`);
    }
    try {
      const { ciphertext, iv, tag } = this.encryption.encrypt(value);
      const entry: CacheEntry = { data: ciphertext, iv, tag, timestamp: Date.now() };
      this.localCache.set(key, entry);
      await this.replicateToRemote(endpoint, key, entry);
      this.circuitBreaker.recordSuccess(endpoint);
    } catch (err) {
      this.circuitBreaker.recordFailure(endpoint);
      throw err;
    }
  }

  async get(key: string): Promise<Buffer | null> {
    const entry = this.localCache.get(key);
    if (!entry) return null;
    try {
      return this.encryption.decrypt(entry.data, entry.iv, entry.tag);
    } catch {
      return null;
    }
  }

  private selectEndpoint(key: string): string {
    // Non-cryptographic sharding hash; using SHA-256 avoids relying on the
    // broken MD5 primitive even for non-security uses.
    const hash = crypto.createHash('sha256').update(key).digest();
    const index = hash.readUInt32BE(0) % this.endpoints.length;
    return this.endpoints[index];
  }

  private async replicateToRemote(_endpoint: string, _key: string, _entry: CacheEntry): Promise<void> {
    // Simulate network call with potential failure
    if (Math.random() < 0.1) {
      throw new Error('Network timeout');
    }
  }
}
